package com.careerpilot.modules.careerplan.service;
import com.careerpilot.exception.*;import com.careerpilot.modules.assessment.entity.AttemptStatus;import com.careerpilot.modules.assessment.repository.AssessmentAttemptRepository;import com.careerpilot.modules.auth.entity.User;import com.careerpilot.modules.careerplan.dto.CareerPlanDtos.*;import com.careerpilot.modules.careerplan.entity.*;import com.careerpilot.modules.careerplan.repository.*;import com.careerpilot.modules.careerplan.taxonomy.CareerSkillTaxonomy;import com.careerpilot.modules.careerplan.taxonomy.CareerSkillTaxonomy.*;import com.careerpilot.modules.careerrecommendation.repository.CareerRecommendationRepository;import com.careerpilot.modules.profile.repository.*;import com.careerpilot.modules.resume.analysis.repository.ResumeAnalysisRepository;import jakarta.persistence.EntityManager;import org.springframework.http.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class CareerPlanService{private final CareerPlanRepository plans;private final CareerRoadmapItemRepository items;private final CareerRecommendationRepository recommendations;private final ProfileRepository profiles;private final UserSkillRepository userSkills;private final ResumeAnalysisRepository analyses;private final AssessmentAttemptRepository attempts;private final CareerSkillTaxonomy taxonomy;private final CareerSkillGapService gaps;private final PlacementReadinessService readiness;private final EntityManager entityManager;
 public CareerPlanService(CareerPlanRepository plans,CareerRoadmapItemRepository items,CareerRecommendationRepository recommendations,ProfileRepository profiles,UserSkillRepository userSkills,ResumeAnalysisRepository analyses,AssessmentAttemptRepository attempts,CareerSkillTaxonomy taxonomy,CareerSkillGapService gaps,PlacementReadinessService readiness,EntityManager entityManager){this.plans=plans;this.items=items;this.recommendations=recommendations;this.profiles=profiles;this.userSkills=userSkills;this.analyses=analyses;this.attempts=attempts;this.taxonomy=taxonomy;this.gaps=gaps;this.readiness=readiness;this.entityManager=entityManager;}
 @Transactional public PlanResponse create(User user,CreatePlanRequest request){var recommendation=recommendations.findByIdAndUserId(request.recommendationId(),user.getId()).orElseThrow(()->new NotFoundException("Career recommendation not found"));String selected=request.career().strip();boolean recommended=recommendation.getItems().stream().anyMatch(v->v.getCareer().equalsIgnoreCase(selected));if(!recommended)throw new ApiException(HttpStatus.BAD_REQUEST,"Selected career must be present in the owned recommendation result");CareerDefinition definition=taxonomy.find(selected).orElseThrow(()->new ApiException(HttpStatus.BAD_REQUEST,"Unsupported career"));CareerPlan plan=plans.findByUserId(user.getId()).orElseGet(CareerPlan::new);if(plan.getId()!=null){plan.getItems().clear();entityManager.flush();}plan.setUser(user);plan.setRecommendation(recommendation);plan.setSelectedCareer(definition.career());plan.setTaxonomyVersion(CareerSkillTaxonomy.VERSION);plan.setReadinessVersion(PlacementReadinessService.VERSION);var gap=gaps.analyze(definition,userSkills.findByUserIdOrderBySkillDisplayName(user.getId()));generate(plan,definition,gap,user.getId());return response(plans.save(plan),user);}
 @Transactional(readOnly=true)public PlanResponse current(User user){return plans.findByUserId(user.getId()).map(v->response(v,user)).orElse(null);}
 @Transactional public PlanResponse updateStatus(User user,UUID itemId,UpdateStatusRequest request){CareerRoadmapItem item=items.findByIdAndCareerPlanUserId(itemId,user.getId()).orElseThrow(()->new NotFoundException("Roadmap item not found"));item.setStatus(request.status());item.setStatusSource(RoadmapStatusSource.USER_REPORTED);items.save(item);return response(plans.findByUserId(user.getId()).orElseThrow(),user);}
 private void generate(CareerPlan plan,CareerDefinition definition,SkillGapResponse gap,UUID userId){Map<String,SkillGapItem>state=new HashMap<>();gap.present().forEach(v->state.put(v.skill(),v));gap.needsImprovement().forEach(v->state.put(v.skill(),v));gap.missingCore().forEach(v->state.put(v.skill(),v));gap.missingSupporting().forEach(v->state.put(v.skill(),v));int order=1,index=0;for(RequiredSkill skill:definition.coreSkills()){int stage=index++<2?1:2;add(plan,stage,stage==1?"Foundation":"Core Role Skills",order++,skill.displayName(),skill.displayName(),"This is a curated core requirement for "+definition.career()+".",action(state.get(skill.displayName())),status(state.get(skill.displayName())),source(state.get(skill.displayName())));}for(RequiredSkill skill:definition.supportingSkills())add(plan,3,"Practical Application",order++,skill.displayName(),skill.displayName(),"This supporting skill strengthens practical "+definition.career()+" work.",action(state.get(skill.displayName())),status(state.get(skill.displayName())),source(state.get(skill.displayName())));add(plan,3,"Practical Application",order++,definition.career()+" portfolio project",null,"A focused project can provide truthful evidence of applied skills.","Build one small role-specific project and document only work you actually completed.",RoadmapStatus.NOT_STARTED,RoadmapStatusSource.PLANNED);boolean resumeReady=analyses.findFirstByResumeUserIdAndResumeActiveTrueOrderByCreatedAtDesc(userId).isPresent();add(plan,4,"Placement Preparation",order++,"Resume readiness",null,"A reviewed resume helps communicate verified skills and projects.","Run deterministic resume analysis and address its truthful findings.",resumeReady?RoadmapStatus.READY:RoadmapStatus.NOT_STARTED,resumeReady?RoadmapStatusSource.SYSTEM_EVIDENCE:RoadmapStatusSource.PLANNED);boolean assessed=attempts.findFirstByUserIdAndStatusOrderByCreatedAtDesc(userId,AttemptStatus.SUBMITTED).isPresent();add(plan,4,"Placement Preparation",order,"Assessment practice",null,"Completed assessments provide structured practice evidence.","Complete a relevant assessment and review the skill breakdown.",assessed?RoadmapStatus.READY:RoadmapStatus.NOT_STARTED,assessed?RoadmapStatusSource.SYSTEM_EVIDENCE:RoadmapStatusSource.PLANNED);}
 private void add(CareerPlan p,int stage,String stageName,int order,String topic,String skill,String why,String action,RoadmapStatus status,RoadmapStatusSource source){CareerRoadmapItem item=new CareerRoadmapItem();item.setCareerPlan(p);item.setStageOrder(stage);item.setStageName(stageName);item.setItemOrder(order);item.setTopic(topic);item.setSkillName(skill);item.setWhyItMatters(why);item.setNextAction(action);item.setStatus(status);item.setStatusSource(source);p.getItems().add(item);}private String action(SkillGapItem item){return item==null?"Build and document a truthful practical example.":item.nextAction();}private RoadmapStatus status(SkillGapItem item){return item!=null&&"PRESENT".equals(item.state())?RoadmapStatus.READY:item!=null&&"NEEDS_IMPROVEMENT".equals(item.state())?RoadmapStatus.IN_PROGRESS:RoadmapStatus.NOT_STARTED;}private RoadmapStatusSource source(SkillGapItem item){return item!=null&&("PRESENT".equals(item.state())||"NEEDS_IMPROVEMENT".equals(item.state()))?RoadmapStatusSource.PROFILE_EVIDENCE:RoadmapStatusSource.PLANNED;}
 private PlanResponse response(CareerPlan plan,User user){var profile=profiles.findByUserId(user.getId()).orElseThrow(()->new NotFoundException("Student profile not found"));var definition=taxonomy.find(plan.getSelectedCareer()).orElseThrow(()->new ApiException(HttpStatus.CONFLICT,"Stored career taxonomy is unavailable"));var gap=gaps.analyze(definition,userSkills.findByUserIdOrderBySkillDisplayName(user.getId()));var analysis=analyses.findFirstByResumeUserIdAndResumeActiveTrueOrderByCreatedAtDesc(user.getId());var attempt=attempts.findFirstByUserIdAndStatusOrderByCreatedAtDesc(user.getId(),AttemptStatus.SUBMITTED);var ready=readiness.calculate(profile,gap,analysis,attempt);var roadmap=plan.getItems().stream().map(v->new RoadmapItemResponse(v.getId(),v.getStageOrder(),v.getStageName(),v.getItemOrder(),v.getTopic(),v.getSkillName(),v.getWhyItMatters(),v.getNextAction(),v.getStatus(),v.getStatusSource(),v.getUpdatedAt())).toList();int progress=roadmap.isEmpty()?0:(int)Math.round(roadmap.stream().mapToInt(v->v.status()==RoadmapStatus.READY?100:v.status()==RoadmapStatus.IN_PROGRESS?50:0).average().orElse(0));List<String>next=roadmap.stream().filter(v->v.status()!=RoadmapStatus.READY).map(RoadmapItemResponse::nextAction).distinct().limit(3).toList();return new PlanResponse(plan.getId(),plan.getRecommendation().getId(),plan.getSelectedCareer(),plan.getTaxonomyVersion(),plan.getCreatedAt(),plan.getUpdatedAt(),gap,ready,roadmap,next,progress);}
}

